function layout(body,page){const title=links.find(([id])=>id===page)?.[1]||'Workspace';return `<div class="m365-workspace"><header class="suite-bar">${appLauncher()}<form class="workspace-search" id="workspace-search" role="search">${uiIcon('search')}<input id="workspace-find" aria-label="Find a workspace task" placeholder="Search tasks and files"><button type="submit" aria-label="Search workspace">↵</button></form>${profileMenu()}</header><div class="suite-body"><div class="suite-inner"><div class="channel-header"><span class="workspace-mark wedding-team-icon"><img src="assets/wedding-operations.png" alt="" width="29" height="29"></span><strong>Wedding operations</strong></div><div class="shell"><aside><h2>Blissify team</h2><p class="channel-label">Pinned</p><a class="pinned-room" href="#office"><span class="workspace-mark wedding-team-icon"><img src="assets/maya-alex.png" alt="" width="29" height="29"></span><span>Maya & Alex<small>Wedding planning team</small></span></a><p class="channel-label">Apps</p><nav aria-label="Planning workspace">${[['Plan',['office','planner']],['Work',['inbox','documents','safety','assistant']],['Coordinate',['handoffs','review','budget']]].map(([group,ids])=>`<div class="sidebar-group"><span>${group}</span>${ids.map(id=>{const name=links.find(([key])=>key===id)?.[1]||id;return `<a class="${page===id?'active':''}" href="#${id}">${uiIcon(appIcons[id])}${name}</a>`}).join('')}</div>`).join('')}</nav><div class="room-progress"><small>ROOM ${esc(room)}<br>${done()} of ${total()} milestones</small><div class="progress-track"><span style="width:${done()/total()*100}%"></span></div></div></aside><main class="workspace"><div class="workspace-command"><span>${uiIcon(appIcons[page])}${esc(title)}</span><a href="#flow">Workshop guide</a><a href="#facilitator">Station setup</a></div>${rolePanel()}<div class="level-strip level-${levelOf(state)}"><strong>Team progress</strong> ${done()} / ${total()} tasks complete <span>·</span> ${esc(syncStatus)}</div><section class="workspace-page">${body}</section></main></div></div></div><nav class="mobile-workspace-nav" aria-label="Quick workspace navigation"><a href="#office">${uiIcon('home')}Workspace</a><a href="#planner">${uiIcon('planner')}Planner</a><a href="#handoffs">${uiIcon('handoff')}Handoffs</a></nav></div>`+footer()}
