async function openAdminRoom(headers){
 const response=await fetch('/api/admin-rehearsal',{method:'POST',headers:{'X-Workshop-Client':'blissify',...headers}});
 const data=await response.json();
 if(!response.ok){const error=new Error(data.error||'Could not start a rehearsal.');error.status=response.status;throw error}
 sessionStorage.setItem(adminKey,JSON.stringify(data));
 sessionStorage.setItem('blissify-station-card:'+data.room,data.cards['VEN-01']);
 if(admin)sessionStorage.removeItem(cardKey);
 roomConnection?.close();
 const url=new URL(location.href);url.searchParams.set('room',data.room);url.hash='planner';location.href=url.href;
}
const row=(label,desc,id,flag)=>`<div class="task-row"><div><strong>${label}</strong><span class="muted">${desc}</span></div><a href="#${id}">${state[flag]?'Review ✓':'Open →'}</a></div>`;
function office(){return layout(`<div class="page-head"><div><h1>Maya & Alex’s wedding</h1><p class="muted">The details make the day. Let’s get them right.</p></div><span class="tag">Final preparations</span></div><div class="summary"><div><b>$20,000</b><span>Approved budget</span></div><div><b>80</b><span>Guests attending</span></div><div><b>${done()} / ${total()}</b><span>Preparations complete</span></div></div><div class="columns"><section><h2>Team task sequence</h2><p>Start independent tasks in parallel, cross-check handoffs, then calculate, approve and report the fraudulent support site. Each task unlocks when its prerequisites are complete.</p><label for="guest-brief">Code on your guest brief card</label><input id="guest-brief" maxlength="24"><div class="actions task-actions"><button data-action="guest-brief">Confirm guest brief</button><a href="#safety">Open AI settings →</a></div><h2>Team handoffs</h2><p>Every station starts independently. Cross-check a colleague’s evidence before combining the plan.</p><div class="role-grid">${roles.map(r=>`<article><strong>${r.name}</strong><p>${r.task}</p><a href="#${r.page}">Open task →</a></article>`).join('')}</div><h2>Today’s priorities</h2>${row('Verify the venue payment','Check the request against your agreement.','inbox','verified')}${row('Prepare the client documents','Share only what the assistant needs.','documents','redacted')}${row('Build and check the wedding plan','Combine your team’s evidence.','assistant','planned')}${row('Approve the final arrangements','Two people check the vendor and total.','budget','approved')}</section><section><h2>A message from Elena</h2>${voiceMessage(7)}<h2>A note from the client</h2><p>“We’re excited for a garden ceremony with all 80 guests. Please keep the step-free route and the meal accommodations. We’d rather simplify the decorations than leave anyone out.”</p><div class="callout">Your colleagues have the agreements, guest requirements, and company policy. Bring their findings together before making a final decision.</div>${state.approved?'<h3>Everything is ready.</h3><p>The wedding is saved. Your team verified the payment, protected the records, and reviewed the plan.</p><a href="#debrief">Open your team debrief →</a>':''}</section></div>`,'office')}

function inbox(){return layout(`<h1>Contacts</h1><section class="report-task"><h2>Report the fraudulent voicemails</h2><p>Review each requested action and report the four fraudulent messages with the correct reasons. You can confirm routine messages as good.</p><p id="fraud-report-progress" role="status">${fraudReportCount(state.reports)} / 4 fraudulent messages correctly reported${state.messagesReported?' · Task complete':''}</p></section><div class="contact-heading"><span>People</span><span>Organization & recent activity</span></div><p class="muted">Open a contact to play their voicemail, read the message, or report a suspicious request. Display names are not identity verification.</p><p class="muted">After Elena’s welcome in the office, split the incoming messages between your teams. Vendor verification and document preparation can happen at the same time.</p><div class="inbox-recordings">${[3,8,6,1,2,5].map(voicemailRow).join('')}</div><section id="vendor-verification"><h2>Verify the venue request</h2><p>Look up Garden House Events in the printed vendor directory and enter its saved trusted contact reference.</p><label class="field"><span>Garden House Events contact reference</span><input id="contact" maxlength="30" placeholder="From the printed directory"></label><div class="actions"><button class="primary" data-action="verify">Contact the saved vendor</button><button data-action="unsafe">Approve the changed account</button></div><div id="verify-result" role="status">${state.verified?'<p>Your callback response is ready below.</p>':'<p class="muted">Contact the saved vendor to receive a callback response.</p>'}</div>${state.verified?voiceMessage(4):''}</section>`,'inbox')}

let redactionTool=false, eraserTool=false;
function edits(){return state.documentEdits??={marked:[],applied:[]}}
function invalidateDocument(){state.privacyConfirmed=false;state.chatAttachments=[];state.chatMessages=[];state.redacted=false;state.planned=false;state.reviewed=false;state.approved=false;state.reply='';}
function documentEditor(){const e=edits();return `<div class="pdf-editor" id="document-editor"><div class="pdf-toolbar"><strong>Client financial summary.pdf</strong><span>1 / 1</span><button data-action="redact-tool" aria-pressed="${redactionTool}">Redact text</button><button data-action="undo-mark" aria-pressed="${eraserTool}" title="Select the eraser, then click an area to restore it">Undo mark (eraser)</button><button class="primary" data-action="apply-redactions">Apply redactions</button></div><div class="pdf-workspace"><aside class="pdf-tools"><h3>All tools</h3><p>Redact</p><p class="muted">Select Redact text to mark areas. Select Undo mark (eraser), then click a marked area or black box to restore it.</p><p><strong>${e.marked.length}</strong> marked<br><strong>${e.applied.length}</strong> applied</p><button data-action="new-document">Start a new copy</button></aside><div class="pdf-canvas"><article class="pdf-page" aria-label="Financial statement"><header><strong>BLISSIFY</strong><span>Financial summary<br>Client file · 1 page</span></header><h2>Wedding account statement</h2><p class="pdf-subtitle">Client financial record</p><dl>${documentFields.map(f=>`<div class="pdf-field"><dt>${esc(f.label)}</dt><dd>${e.applied.includes(f.id)?`<button class="applied-redaction ${eraserTool?'eraser-target':''}" data-action="mark-redaction" data-field="${f.id}" aria-label="${eraserTool?'Restore':'Redacted'} ${esc(f.label)}"></button>`:`<button class="redaction-target ${e.marked.includes(f.id)?'marked':''}" data-action="mark-redaction" data-field="${f.id}" aria-pressed="${e.marked.includes(f.id)}" aria-label="${esc(f.label+': '+f.value)}">${esc(f.value)}</button>`}</dd></div>`).join('')}</dl><p class="pdf-footnote">Use the company policy to decide which information is needed for planning.</p></article></div></div><div class="pdf-bottom"><span role="status">${e.marked.some(id=>!e.applied.includes(id))?'Marked only — apply before sharing.':'Review the applied copy before sharing.'}</span><button data-action="preview-document">Preview shared copy</button><button data-action="download-document">Download shared text copy</button><button class="primary" data-action="share-document">Save prepared copy</button></div></div><section id="document-preview" class="sheet" hidden aria-label="Shared copy preview"></section>`}
function documents(){return layout(`<div class="drive-heading"><strong>▱ Blissify Drive</strong><span>Shared drives / Wedding operations</span></div><h1>Files</h1><div class="drive-list"><div><strong>Client financial summary.pdf</strong><span>Restricted · Privacy officer</span><a href="#document-editor">Open & redact</a></div><div><strong>Prepared financial summary.txt</strong><span>${state.redacted?'Ready for planning · minimized copy':'Waiting for privacy handoff'}</span></div><div><strong>Catering quote</strong><span>Shared · available in assistant attachments</span></div><div><strong>Anonymous guest brief</strong><span>Physical prop · Planning analyst confirms below</span></div></div><p>Prepare the statement for the planning assistant. Keep the useful totals and remove unnecessary information.</p><details><summary>Document request from supplier verification support</summary>${voiceMessage(6)}<button data-action="decline-documents">Decline the unredacted request</button></details><p class="status" id="document-decision">${state.declinedDocuments?'Request declined. Continue with the minimum information needed for planning.':''}</p>${documentEditor()}<p class="status" id="document-share-status" role="status">${state.redacted?'Approved summary prepared for the assistant.':''}</p>`,'documents')}

const attachmentNames={summary:'Prepared financial summary',quote:'Cedar Table catering quote',requirements:'Anonymous guest requirements'};
function assistant(){const history=state.chatMessages||[];const files=state.chatAttachments||[];const safe=checkRedaction(edits().marked,edits().applied).ok;const entrance=assistantView==='chat'&&!history.length&&!mascotGreetingShown;if(entrance)mascotGreetingShown=true;return `<div class="m365-workspace assistant-application"><section class="ai-shell openweb-shell ${history.length?'has-messages':'is-empty'} ${themeDark?'ai-dark':''}" aria-label="Blissify planning assistant"><nav class="ai-sidebar" aria-label="Assistant navigation"><div class="assistant-brand">${appLauncher()}<span class="ai-mascot-avatar"><img src="assets/blissify-ai-mascot.webp" alt="Mr. Planner" width="36" height="36"></span><strong>Mr. Planner</strong><button class="ow-icon" data-action="chat-sidebar" aria-label="Collapse sidebar" aria-expanded="true">${uiIcon('menu')}</button></div><div class="assistant-sidebar-scroll"><button class="ow-new-chat" data-action="new-chat">${uiIcon('edit')}<span>New chat</span></button><button data-action="chat-search">${uiIcon('search')}<span>Search chats</span></button><button data-action="assistant-workspace" class="${assistantView==='workspace'?'selected':''}">${uiIcon('planner')}<span>Workspace</span></button><button data-action="chat-notes">${uiIcon('review')}<span>Notes</span></button><p class="ow-chat-label">Pinned</p><button class="ai-conversation ${assistantView==='chat'?'selected':''}" data-action="chat-current"><img class="assistant-wedding-icon" src="assets/maya-alex.png" alt="" width="32" height="32"><span>Maya & Alex’s wedding</span></button><p class="ow-chat-label">Projects</p><button data-action="assistant-workspace"><img class="assistant-brand-icon" src="assets/wedding-operations.png" alt="" width="24" height="24"><span>Wedding operations</span></button><a href="#planner">${uiIcon('planner')}<span>Team planner</span></a><a href="#handoffs">${uiIcon('handoff')}<span>Team handoffs</span></a><p class="ow-chat-label">Recent</p><button data-action="chat-current">Budget & guest arrangements</button></div><div class="assistant-station"><span class="ow-user-avatar">P</span><div><strong>Planning</strong><small>Room ${esc(room)}</small></div></div><div class="assistant-progress level-${levelOf(state)}"><span class="level-strip">${done()} / ${total()} tasks complete · ${esc(syncStatus)}</span><small>${done()} of ${total()} milestones</small><div class="progress-track"><span style="width:${done()/total()*100}%"></span></div></div></nav><div class="ai-main"><header class="ai-header"><button class="ow-icon ow-expand" data-action="chat-sidebar" aria-label="Expand sidebar" aria-expanded="false">${uiIcon('menu')}</button><strong class="ow-model">Mr. Planner</strong><button class="assistant-view-button" data-action="${assistantView==='chat'?'assistant-workspace':'chat-current'}">${uiIcon(assistantView==='chat'?'planner':'chat')}<span>${assistantView==='chat'?'Workspace':'Back to chat'}</span></button>${profileMenu()}</header><div class="assistant-chat-view" ${assistantView==='chat'?'':'hidden'}><div class="ai-thread" role="log" aria-label="Planning conversation" aria-live="polite">${history.length?history.map(m=>`<article class="ai-message ${m.role==='user'?'ai-user':'ai-answer'}"><strong>${m.role==='user'?'You':'<img class="assistant-message-icon ai-mascot-message" src="assets/blissify-ai-mascot.webp" alt="" width="24" height="24"> Mr. Planner'}</strong><div>${esc(m.text)}</div>${m.files?.length?'<p class="ai-sources">Attached: '+m.files.map(id=>esc(attachmentNames[id])).join(' · ')+'</p>':''}</article>`).join(''):`<div class="ai-welcome"><span class="ai-mascot-avatar ai-mascot-welcome ${entrance?"mascot-enter":""}" role="img" aria-label="Mr. Planner"><img src="assets/blissify-ai-mascot.webp" alt="Mr. Planner" width="72" height="72"></span><h1>Hi, I’m Mr. Planner</h1><p class="planner-intro">Planning team, start with the anonymous guest brief in the wedding office. Then open Workspace and inspect the supplier quote. Once the team’s handoffs are ready, drag the prepared financial summary, checked quote, and anonymous guest brief into the input tray. Review what you’re sharing, then ask me to calculate the wedding plan.</p></div>`}</div><div class="ai-compose-area"><div class="ai-attachments">${files.map(id=>`<span class="ai-file">${esc(attachmentNames[id])}<button data-action="remove-attachment" data-attachment="${id}" aria-label="Remove ${esc(attachmentNames[id])}">×</button></span>`).join('')}</div><label class="sr-only" for="prompt">Message the planning assistant</label><div class="ai-composer"><details class="ai-attachment-menu"><summary aria-label="Add attachments">+</summary><div><strong>Available files</strong>${availableFiles().map(id=>`<button data-action="attach-${id}">${esc(attachmentNames[id])}</button>`).join('')}<p>Attach only the prepared documents needed for this task.</p></div></details><textarea id="prompt" maxlength="1200" placeholder="How can I help you today?">${esc(state.prompt||'')}</textarea><span class="ow-tool">${uiIcon('planner')} Budget calculator</span><button data-action="preview-input" class="input-preview-button">${uiIcon('shield')} Review input</button><button class="ai-send" data-action="chat-send" aria-label="Send message">↑</button></div><p class="ai-disclaimer">Workshop guidance uses built-in lessons. Final calculations run in your browser.</p><details class="chat-template-menu" ${!history.length?'open':''}><summary>Workshop prompt templates</summary><div class="ow-suggestions">${helpTemplates.map(([id,title,prompt])=>`<button data-action="help-template" data-template="${id}"><strong>${esc(title)}</strong><span>${esc(prompt)}</span></button>`).join('')}</div></details></div></div><section class="assistant-workbench" ${assistantView!=='chat'?'':'hidden'} aria-label="Wedding planning workspace">${assistantWorkspace()}</section></div></section></div>`}
function availableFiles(){return ['quote',...(state.guestBrief?['requirements']:[]),...(state.redacted&&checkRedaction(edits().marked,edits().applied).ok?['summary']:[])]}
function workspaceFilePanel(){return `<aside class="workspace-file-panel" aria-label="Available workspace files"><h2>Files</h2><p class="muted">Drag a file into the workspace, or choose Add.</p>${availableFiles().map(id=>`<article class="workspace-file" draggable="true" data-workspace-file="${id}">${uiIcon('file')}<strong>${esc(attachmentNames[id])}</strong><button data-action="attach-${id}" aria-label="Add ${esc(attachmentNames[id])} to workspace">${(state.chatAttachments||[]).includes(id)?'Added':'Add'}</button></article>`).join('')}</aside>`}
function assistantWorkspace(){const files=(state.chatAttachments||[]).filter(id=>availableFiles().includes(id));return `<header class="assistant-workspace-heading"><div><h1>Wedding workspace</h1><p>Drag the prepared financial summary, catering quote, and anonymous guest requirements from Files into Your working files, or use each file’s Add button. Then choose Continue with these files in chat to calculate the wedding plan.</p></div></header><div class="assistant-workspace-grid"><section id="chat-sources" data-workspace-drop aria-label="Document workspace"><div class="workspace-dropzone"><h2>Your working files</h2><p>Drop files here to work with them.</p><div class="ai-attachments">${files.map(id=>`<span class="ai-file">${esc(attachmentNames[id])}<button data-action="remove-attachment" data-attachment="${id}" aria-label="Remove ${esc(attachmentNames[id])}">×</button></span>`).join('')}</div></div>${files.includes('quote')?`<details class="workspace-disclosure"><summary>Preview catering quote</summary>${supplierQuote()}</details><button class="primary" data-action="injection">${state.injection?'Review flagged instruction':'Inspect and flag supplier instructions'}</button><p class="status">${state.injection?'Flagged and removed from AI input. Pricing facts are retained.':'Select the embedded instruction and explain why it is unsafe.'}</p>`:''}${files.includes('summary')?`<details class="workspace-disclosure"><summary>Review prepared financial summary</summary><dl>${sanitizedFields(edits().applied).map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value)}</dd></div>`).join('')}</dl></details>`:''}${files.includes('requirements')?'<details class="workspace-disclosure"><summary>Review anonymous guest requirements</summary><p>80 guests · step-free access · meal accommodations</p></details>':''}${files.length?'<button data-action="chat-current">Continue with these files in chat →</button>':''}</section>${workspaceFilePanel()}</div>`}


function budget(){return layout(`<h1>Budget & final approval</h1><p>Check the totals with your finance and guest requirements teams.</p><div class="table-scroll"><table><thead><tr><th>Approved item</th><th>Cost</th></tr></thead><tbody>${[['Venue','$7,000'],['Catering including 20% charge','$3,840'],['Photography','$2,000'],['Music','$1,000'],['Cake','$600'],['Decorations','$1,400'],['Total','$15,840'],['Remaining reserve','$4,160']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div><div class="callout">Venue deposit: $2,000, payable to Garden House Events, account ending 4821. The deposit is included in the $7,000 venue package; do not add it twice.</div><h2>Two-person approval</h2><p>One person checks the website. A second person checks the physical vendor agreement and finance envelope.</p><label class="field"><span>Verifier’s approval code</span><input id="approval" maxlength="30" placeholder="From the finance envelope"></label><div class="checks"><label><input id="second" type="checkbox">A second teammate verified the vendor, account, amount, and guest requirements</label></div><button class="primary" data-action="approve">Approve the wedding plan</button><p class="muted">This pilot uses a physical verifier code. Connected stations share progress; the second-person approval still uses the separate physical finance card.</p>${state.supportReported?'<p class="status">The wedding is saved. All team milestones are complete.</p><a href="#debrief">Open debrief →</a>':state.approved?'<p class="status">Wedding plan approved.</p>':''}`,'budget')}
const phases=[["0–5","Introduction","Explain the wedding assignment and play Elena’s welcome (7). Assign Coordination, Privacy, Planning, and Finance roles. No participant accounts are needed."],["5–10","Set up the stations","Open your labeled folder and sign in with the team ID card inside. Start the independent tasks as soon as the stations are ready."],["10–22","Parallel investigations","Vendor team reviews the venue request (3) and Elena’s urgent voicemail (8), then uses the trusted directory to reveal the callback (4). Privacy team reviews the document request (6) and prepares a minimized summary. Planning team checks guest requirements and quotes. These tasks proceed concurrently."],["22–32","Plan with AI","Combine the findings, reject the attachment’s unrelated instructions, and make one useful AI request. Check the source inputs and confirm the assistant’s calculation and guest accommodations."],["32–40","Final approval","A second reviewer checks the approved vendor account, budget, and accommodations. Complete the joint approval. Allow recovery without time penalties."],["40–45","Debrief and exit","Reveal the voice impersonation and document attack. Discuss trusted verification, minimum necessary information, and human review. For a 50-minute session, use the extra five minutes for gameplay and begin this debrief at minute 45."]];
function flow(){return top()+`<main class="wrap"><div class="page-head"><div><h1>Save the Wedding</h1><p>45–50-minute cooperative pilot · one room · one computer per role</p></div><button class="no-print" data-action="print">Print flow & props</button></div><p>No participant Lite Foundry login. The wedding website receives answers and tracks the room’s preparations.</p><ol class="timeline">${phases.map(([t,h,p],i)=>`<li><div class="time">${t} min</div><div><h2>${h}</h2><p>${p}</p>${i===2?'<div class="lanes"><div class="lane"><strong>Vendor team</strong><br>Contact directory<br>Agreement and invoice</div><div class="lane"><strong>Privacy team</strong><br>Company policy<br>Statement and guest list</div><div class="lane"><strong>Planning team</strong><br>Catering quote<br>Budget and guest needs</div></div><p><strong>Dependency:</strong> findings from all three teams are needed for final approval. Document preparation can proceed while vendor verification is underway.</p>':''}</div></li>`).join('')}</ol><h2>Facilitation for the short session</h2><ul><li>Required recordings: welcome (7), venue request (3), urgent Elena voicemail (8), callback (4), and document request (6).</li><li>Baker (1), decorations (2), and bank (5) are optional extras.</li><li>Put each team ID card in its matching role folder before distributing the folders. Keep the final approval slip with the facilitator until independent review.</li><li>Give a targeted hint after about two minutes without progress.</li><li>Use recovery feedback without time penalties. Have participants open More options, report a message, and select a reason. Reporting does not verify the caller or block a payment. Require one useful request with safe attachments and a source review. Let the assistant do the arithmetic.</li></ul><h2>Printable prop set</h2>${props()}<p class="muted">Target 45 minutes: 5 minutes for introduction, 35 minutes for gameplay, and 5 minutes for debrief and exit. For a 50-minute session, extend gameplay by five minutes and begin the debrief at minute 45.</p></main>`+footer()}
function props(){return `<section class="prop"><h3>Coordination · Trusted vendor directory</h3><p>Garden House Events · saved contact reference: <strong>GARDEN-4821</strong>. Use the established directory, not contact details supplied in an urgent message.</p></section><section class="prop"><h3>Finance · Signed venue agreement</h3><p>Garden House Events · Maya &amp; Alex. Digital-copy access code: <strong>VENUE-4821</strong>. Venue package $7,000. Deposit $2,000 included in the package. Approved account ending <strong>4821</strong>. Any change requires independent confirmation and two-person approval.</p></section><section class="prop"><h3>Privacy · Information handling policy</h3><p>For this task, share budget totals, relevant costs, aggregate meal counts, and anonymous requirements. Do not share account numbers, login codes, client contacts, or named medical information. Use the approved planning workspace.</p></section><section class="prop"><h3>Planning · Anonymous guest brief</h3><p>Maya &amp; Alex · Brief reference: <strong>GUEST-80</strong>. 80 guests. Preserve step-free access and all agreed meal accommodations.</p></section><section class="prop"><h3>Facilitator holdback · Final approval slip</h3><p>Second reviewer: independently check vendor, approved account, deposit, and total. Approval code: <strong>TOGETHER-4821</strong>. Total plan cost: $15,840. Remaining reserve: $4,160.</p></section>`}
function facilitator(){return top()+`<main class="wrap"><h1>Rehearsal controls</h1><p>This workshop uses room <strong>${esc(room)}</strong>. It is not a secured instructor console. Generate one room-specific ID card for each role. </p><div class="actions"><a href="#admin">Open admin rehearsal</a><button data-action="new">Create a fresh local room</button><button data-action="reset">Reset this rehearsal</button><a class="primary" href="#flow">Open flow & printable props</a><button data-action="export">Download progress report</button></div><h2>Team ID cards</h2><p>Enter the facilitator code to generate the four cards for this room. Put one card in each role folder and keep the facilitator code private.</p><form id="station-card-setup"><label for="room-code">Facilitator workshop code</label><input id="room-code" type="password" maxlength="200" autocomplete="off" required><button type="submit">Generate team ID cards</button><p id="card-setup-feedback" role="status"></p></form>${printableCards?cardSheet():''}<h2>Readiness</h2><ul><li>Business navigation, answer checks, recovery, and final approval: interactive.</li><li>Assistant: built-in workshop guidance and browser-based budget calculation.</li><li>All eight supplied recordings are connected. Message 1 uses the audio extracted from your MP4. Elena’s urgent request is a voicemail; no deepfake video is used.</li><li>Two-person approval: a separate finance role and physical code; connected stations share milestone progress.</li><li>Figma: palette, type choices, and landing structure adapted; your supplied wedding photographs are now included.</li></ul><h2>Facilitator setup</h2><ol><li>Put one printed prop in each of the four role folders. Keep the final approval slip in a separate envelope until independent review.</li><li>Assign Coordination, Privacy, Planning, and Finance groups. Rotate the screen operator.</li><li>Use the room and code on each card to sign its station in.</li><li>Test the laptop speakers. Use the 45-minute flow: play Elena’s welcome, then split into parallel investigations. The three optional recordings are collapsed in the Inbox. The venue callback appears after the trusted contact check. Each recording has expandable script text.</li></ol><details><summary>Answer key</summary><p>Local rehearsal login IRIS-24 · vendor GARDEN-4821 · apply redactions to the holder name, account number, contact, internal ID, and individual guest note; keep all totals · assistant calculates catering $3,840; confirm source inputs · preserve accessibility and meals · verifier TOGETHER-4821.</p></details></main>`+footer()}
function cardSheet(){
 const loginUrl=location.origin+location.pathname+'?room='+encodeURIComponent(room)+'#login';
 return `<section id="team-card-sheet"><div class="role-grid">${roles.map(role=>`<article class="team-id-card"><p>Blissify · Wedding Operations</p><h3>${esc(role.name)}</h3><p>${esc(role.task)}</p><dl><dt>Room ID</dt><dd>${esc(room)}</dd><dt>Station code</dt><dd><code>${esc(printableCards[role.id])}</code></dd></dl><p>Sign in at <a href="${esc(loginUrl)}">${esc(loginUrl)}</a>.</p></article>`).join('')}</div><button type="button" class="no-print" data-action="print-cards">Print team ID cards</button></section>`;
}

function debrief(){return layout(`<h1>${state.supportReported?'The wedding is saved.':state.approved?'Wedding plan approved':'Your team’s review'}</h1><p>${done()} of ${total()} milestones complete. ${state.incidents} unsafe actions recorded.</p><h2>What protected the wedding?</h2><ul><li>Checking an urgent request against a trusted contact. The venue callback confirms account 4821, not 7719.</li><li>Look in a message’s More options menu for reporting actions. Names and locations vary by app; use your organization’s reporting process when no option is available.</li><li>A familiar voice does not prove who is calling. Compare Elena’s welcome with the message asking you to skip verification.</li><li>Sharing only necessary information with the approved assistant.</li><li>Treating supplier documents as evidence, not authority to override policy.</li><li>Checking AI recommendations against the original quote.</li><li>Preserving guest accommodations and requiring a second reviewer.</li></ul><p>Discuss which choices transfer to invoices, student information, research data, and everyday campus work.</p><button data-action="export">Download room report</button>`,'office')}
function vendors(){return top()+`<main class="wrap"><h1>Our wedding partners</h1><p>Meet the people bringing Maya and Alex’s celebration together.</p><div class="vendor-grid">${[['Garden House Events','Venue and ceremony · approved package $7,000'],['Cedar Table Catering','80 guests · $40 per guest plus 20% service charge'],['Étoile Patisserie','Celebration cake · $600']].map(([n,p])=>`<section class="vendor"><h3>${n}</h3><p>${p}</p><a href="#${state.open?'inbox':'login'}">Open planning office →</a></section>`).join('')}</div></main>`+footer()}
