async function makePhoneInvite(){
 if(!roomConnectionReady||!stationCard||state.phoneAudit||phoneInviteStatus==='Generating…')return;
 const rerender=()=>{if(location.hash==='#phone-audit')render()};
 phoneInviteStatus='Generating…';rerender();
 try{
  const response=await fetch('/api/phone-invite?room='+encodeURIComponent(room),{headers:{'X-Workshop-Client':'blissify','X-Station-Card':stationCard}});
  const data=await response.json();
  if(!response.ok)throw Error(data.error||'Could not generate a QR code.');
  const {default:makeQr}=await import('./assets/vendor/qrcode-generator.mjs');
  const qr=makeQr(0,'M');qr.addData(location.origin+'/phone-audit.html#'+data.token);qr.make();
  phoneInvite={image:qr.createDataURL(5,20),expires:data.expires};
  phoneInviteStatus='Waiting for the phone audit.';
 }catch(error){phoneInviteStatus=error.message}
 rerender();
}
