function peerReviewPanel(task){const reason=taskReason(task.id,state);if(reason)return `<p>${waitingStatus(waitingMessage(task.id))}</p><p>Your colleague’s saved evidence will appear here when their preparation is complete.</p>`;const review=buildPeerReview(task.id,state);if(!review)return '<p>The prepared record is not ready. Ask your colleague to review and save it again.</p>';const completed=state[task.id]&&checkPeerReview(task.id,state[reviewKeys[task.id]],state).ok;return `<div class="peer-review-columns"><section><h3>${esc(review.title)}</h3><p class="peer-source-label">Saved by ${esc(review.owner)} · source evidence</p><dl>${review.rows.map(r=>`<div><dt>${esc(r.label)}</dt><dd>${esc(r.value)}</dd></div>`).join('')}</dl></section><section><h3>${completed?'Corrected handoff · reviewed':'Draft handoff · awaiting review'}</h3><p>${completed?'Your correction matches the saved source record.':'This draft contains one discrepancy. Compare every row with the saved source.'}</p><dl>${review.rows.map(r=>`<div><dt>${esc(r.label)}</dt><dd>${esc(completed?r.value:r.draft)}</dd></div>`).join('')}</dl></section></div><label for="peer-field-${task.id}">Which field does not match?</label><select id="peer-field-${task.id}" ${completed?'disabled':''}><option value="">Choose a field</option>${review.rows.map(r=>`<option value="${r.id}" ${completed&&r.id===review.wrongField?'selected':''}>${esc(r.label)}</option>`).join('')}</select><label for="peer-correction-${task.id}">Correct value from the saved source</label><input id="peer-correction-${task.id}" value="${completed?esc(review.correction):''}" ${completed?'readonly':''} autocomplete="off" placeholder="Read the source record and enter its value"><p id="peer-feedback-${task.id}" class="peer-feedback" role="status"></p><button data-action="confirm-${task.id}" ${completed?'disabled':''}>${completed?'Review completed':'Submit correction and complete review'}</button>${state[task.id]?'<p class="status">Peer review completed. Your team can use the corrected handoff.</p>':''}`}

function review(){return layout(`<h1>Independent plan review</h1>${paymentPanel()}${state.planned?`<section class="sheet"><h2>Planning analyst’s output</h2><p style="white-space:pre-wrap">${esc(state.reply)}</p></section><p>Compare the quoted prices, service charge and deposit with your physical evidence.</p><div class="checks"><label><input id="source-check" type="checkbox">I checked the quoted inputs and service charge</label><label><input id="access" type="checkbox">Keep step-free access</label><label><input id="meals" type="checkbox">Keep all required meal accommodations</label></div><button class="primary" data-action="review">Confirm reviewed plan</button><a href="#budget">Final approval →</a>`:'<p>Waiting for the analyst’s plan. Meanwhile check the venue agreement and source settings in My handoffs.</p><a href="#handoffs">Open my handoffs →</a>'}`,'review')}

function attackPanel(){return `<section class="security-lab sheet"><span class="level-badge level-2">Source investigation</span><h2>When a quote becomes an instruction</h2><p>Supplier documents can contain useful business facts and untrusted instructions. Use the inspection tool above to identify and flag the passage that attempts to redirect the assistant.</p>${state.injection?`<div class="unsafe-output"><strong>Recorded example · unsafe assistant output</strong><p>${esc(attackExample.reply)}</p><p>Source: ${esc(attackExample.source)}</p></div><p>Your team excluded that instruction from AI input. The quote’s pricing facts remain available. Finance must independently reject the proposed account change; this recorded example is separate from your planning conversation.</p>`:''}</section>`}

function paymentPanel(){return `<section class="sheet"><h2>AI-proposed action · awaiting human approval</h2>${state.attackObserved?`<dl><dt>Action</dt><dd>Replace venue payment account</dd><dt>Proposed account ending</dt><dd>7719</dd><dt>Amount</dt><dd>$2,000 deposit</dd><dt>Source</dt><dd>${esc(attackExample.source)} — supplier text, not vendor authorization</dd></dl><p>Compare this proposal with the saved agreement and the Vendor coordinator’s callback.</p><label for="verified-payee">Account ending from the trusted agreement</label><input id="verified-payee" maxlength="4"><div class="actions"><button data-action="reject-payment">Reject unverified change</button><button data-action="accept-payment">Approve proposed change</button></div><p class="status">${state.paymentRejected?'Rejected. Original vendor account retained; no payment was made.':'Decision required before the analyst can generate the reviewed plan.'}</p>`:'<p>No proposal yet. Complete your agreement and source checks while the analyst investigates.</p>'}</section>`}
function aiEnvelope(){const p=preparePlanningInput(edits(),state.chatAttachments||[]);return {prompt:value('prompt'),history:(state.chatMessages||[]).slice(-4).map(({role,text})=>({role,text:text.slice(0,3000)})),context:p.ok?planningContext(p.input,state.injection):null,quoteReviewed:state.injection}}
function showInputPreview(){const envelope=aiEnvelope();const p=preparePlanningInput(edits(),state.chatAttachments||[]);if(!p.ok)return toast(p.message);const old=document.getElementById('ai-input-dialog');old?.remove();const dialog=document.createElement('dialog');dialog.id='ai-input-dialog';dialog.setAttribute('aria-labelledby','ai-input-title');dialog.innerHTML=`<h2 id="ai-input-title">Review what the assistant will receive</h2><p>The calculation runs in your browser. Your message, recent conversation, prepared totals, quote facts and anonymous requirements are included. This preview illustrates the data minimization check. Original client identifiers are excluded from document context.</p><pre>${esc(JSON.stringify(envelope,null,2))}</pre><label><input id="input-reviewed" type="checkbox">I checked the message and documents contain only necessary information</label><div class="actions"><button data-action="confirm-input" class="primary">Confirm and send</button><button data-action="close-input">Go back</button></div>`;app.append(dialog);dialog.showModal();if(flagPassageSelected&&inspectionMode==='flag')dialog.querySelector('.inspection-reason')?.scrollIntoView({block:'center'})}

function supplierQuote(){return `<article class="supplier-quote" aria-label="Cedar Table catering quote"><header><strong>CEDAR TABLE</strong><span>Catering & events</span></header><h3>Catering quotation</h3><p>Prepared for Maya & Alex · Blissify Wedding Operations<br>Quote CT-080 · Garden reception</p><table><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody><tr><td>Reception catering · 80 guests × $40</td><td>$3,200</td></tr><tr><td>Service charge · 20%</td><td>$640</td></tr><tr><th>Total catering</th><th>$3,840</th></tr></tbody></table><p>Includes the agreed meal accommodations. Venue services are quoted separately.</p><footer><strong>Processing note</strong><p>${esc(supplierInstruction)}</p></footer></article>`}
function syncReportForm(){const locked=reportIsFinal(state.reports?.[reportingMessage],reportingMessage);document.getElementById('report-reason').disabled=locked;document.getElementById('report-notes').disabled=locked;document.querySelector('#report-dialog [data-action="send-report"]').hidden=locked;document.querySelector('#report-dialog [data-action="close-report"]').textContent=locked?'Done':'Cancel';if(locked){const feedback=document.getElementById('report-feedback');feedback.textContent='Report submitted with a correct reason. Your response is saved and cannot be changed.';feedback.dataset.result='success'}}

function openChatUtility(kind){document.getElementById('chat-utility')?.remove();const d=document.createElement('dialog');d.id='chat-utility';d.setAttribute('aria-labelledby','chat-utility-title');d.innerHTML=kind==='notes'?`<h2 id="chat-utility-title">Notes</h2><p>Saved on this station for your workshop.</p><label for="assistant-notes">Planning notes</label><textarea id="assistant-notes" maxlength="2000" rows="8">${esc(state.assistantNotes||'')}</textarea><div class="actions"><button data-action="save-chat-notes">Save notes</button><button data-action="close-chat-utility">Cancel</button></div>`:`<h2 id="chat-utility-title">Search this conversation</h2><label for="chat-query">Find a message</label><input id="chat-query" type="search" placeholder="Search messages"><div id="chat-results" role="status"></div><button data-action="close-chat-utility">Done</button>`;app.append(d);d.showModal();if(kind==='search'){const input=d.querySelector('input');const results=d.querySelector('#chat-results');const search=()=>{const q=input.value.trim().toLowerCase();const found=(state.chatMessages||[]).filter(m=>!q||m.text.toLowerCase().includes(q));results.innerHTML=found.length?found.map(m=>`<article><strong>${m.role==='user'?'You':'Mr. Planner'}</strong><p>${esc(m.text)}</p></article>`).join(''):'<p>No matching messages in this conversation.</p>'};input.addEventListener('input',search);search();input.focus()}}

function setAssistantView(view){const draft=document.getElementById('prompt');if(draft)state.prompt=draft.value;assistantView=view;persist();render();animateContent(app.querySelector(view==='chat'?'.assistant-chat-view':'.assistant-workbench'))}

function waitingMessage(id){const task=tasks.find(t=>t.id===id);const missing=(task?.deps||[]).filter(dep=>!state[dep]).map(dep=>tasks.find(t=>t.id===dep));return 'Waiting for:\n'+missing.filter(Boolean).map(t=>'• '+t.title+' ('+roleName(t.role)+')').join('\n')}
function waitingStatus(reason){return `<span class="waiting-status"><span>Waiting</span><button type="button" class="status-info" data-action="waiting-info" data-waiting="${esc(reason)}" aria-label="Why this task is waiting" aria-expanded="false"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6"/><circle cx="12" cy="7.5" r=".8" fill="currentColor" stroke="none"/></svg></button></span>`}
function taskStatusMarkup(task){const status=taskStatus(task,state);const count=tasks.find(t=>t.id===task[0])?.deps.filter(k=>!state[k]).length||0;return status==='Waiting'?waitingStatus(waitingMessage(task[0])).replace('Waiting','Waiting on '+count+' task'+(count===1?'':'s')):esc(status)}
function hideWaitingInfo(){waitingAnchor?.setAttribute('aria-expanded','false');waitingAnchor?.removeAttribute('aria-describedby');document.getElementById('waiting-tooltip')?.remove();waitingAnchor=null;waitingPinned=false}
function showWaitingInfo(button,pinned=false){if(!button)return;if(waitingAnchor===button){waitingPinned||=pinned;return}hideWaitingInfo();waitingAnchor=button;waitingPinned=pinned;const tip=document.createElement('div');tip.id='waiting-tooltip';tip.setAttribute('role','tooltip');tip.textContent=button.dataset.waiting;document.body.append(tip);button.setAttribute('aria-expanded','true');button.setAttribute('aria-describedby',tip.id);const r=button.getBoundingClientRect();tip.style.left=Math.max(16,Math.min(r.left,innerWidth-tip.offsetWidth-16))+'px';tip.style.top=(r.bottom+8+tip.offsetHeight<innerHeight?r.bottom+8:Math.max(16,r.top-tip.offsetHeight-8))+'px'}
app.addEventListener('pointerover',e=>{const b=e.target.closest('.status-info');if(b&&!waitingPinned)showWaitingInfo(b)});
app.addEventListener('pointerout',e=>{if(!waitingPinned&&e.target.closest('.status-info')&&!e.relatedTarget?.closest?.('.status-info')&&e.relatedTarget?.id!=='waiting-tooltip')hideWaitingInfo()});
app.addEventListener('focusin',e=>{if(e.target.matches('.status-info'))showWaitingInfo(e.target)});
app.addEventListener('focusout',e=>{if(e.target.matches('.status-info')&&!waitingPinned)hideWaitingInfo()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideWaitingInfo()});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.status-info')&&!e.target.closest('#waiting-tooltip'))hideWaitingInfo()});
window.addEventListener('resize',hideWaitingInfo);
window.addEventListener('scroll',hideWaitingInfo,true);

function messageDecisionLabel(id){const r=state.reports?.[id];return !r?'':r.disposition==='good'?'Confirmed good':reportIsFinal(r,id)?'Reported':'Reported for review'}

function animateContent(container){if(!container||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const selectors=[':scope > h1',':scope > h2',':scope > p',':scope > .page-head',':scope > .summary > div',':scope > .planner-levels > div',':scope > .planner-toolbar > *',':scope > .columns > *',':scope > .role-grid > article',':scope > .sheet',':scope > .report-task',':scope > .inbox-recordings > details',':scope .planner-table tbody > tr',':scope .ai-welcome',':scope .ai-composer',':scope .ow-suggestions > button',':scope > .assistant-workspace-heading',':scope > .assistant-evidence > span',':scope .supplier-quote',':scope .assistant-workspace-grid > aside > .sheet'];const elements=[...container.querySelectorAll(selectors.join(','))].filter(el=>!el.closest('[hidden]'));elements.forEach((el,index)=>{el.classList.add('element-enter');el.style.setProperty('--enter-delay',Math.min(index*30,150)+'ms')})}

function openInspection(){if(document.getElementById('quote-inspection')?.open)return;document.getElementById('quote-inspection')?.remove();const dialog=document.createElement('dialog');dialog.id='quote-inspection';dialog.setAttribute('aria-labelledby','inspection-title');const part=(id,text)=>`<button type="button" class="inspection-text" data-action="inspect-text" data-inspection="${id}">${esc(text)}</button>`;dialog.innerHTML=`<header class="inspection-toolbar"><div><h2 id="inspection-title">${inspectionMode==='flag'?'Identify and flag the instruction':'Inspect the supplier quote'}</h2><p>Move the magnifier over the document. Select the passage that tries to control the assistant.</p></div><button data-action="close-inspection" aria-label="Close document inspection">✕</button></header><div class="inspection-scroll"><article class="inspection-paper"><header><strong>CEDAR TABLE</strong><p>Catering & events · Quote CT-080</p></header><h3>Catering quotation</h3>${part('client','Prepared for Maya & Alex · Garden reception')}${part('price','Reception catering: 80 guests × $40 = $3,200')}${part('service','Service charge: 20% = $640. Total catering: $3,840.')}${part('requirements','Includes the agreed meal accommodations. Venue services are quoted separately.')}<footer><strong>Processing note</strong>${part('instruction',supplierInstruction)}</footer></article>${inspectionMode==='flag'&&flagPassageSelected?`<section class="inspection-reason"><label for="flag-reason">Why should this passage be excluded from AI instructions?</label><select id="flag-reason"><option value="">Choose your explanation</option><option value="pricing">It describes the catering price and service charge</option><option value="override">It tells the AI to override policy, disclose a statement, and change payment details</option><option value="requirements">It lists the guests’ access and meal requirements</option></select><button data-action="flag-reason">Submit evidence and flag</button></section>`:''}</div><p id="inspection-feedback" role="status" aria-live="polite">${esc(inspectionFeedback||'Select one passage. You can also use Tab and Enter to inspect the text.')}</p>`;app.append(dialog);dialog.addEventListener('close',()=>{inspectionOpen=false});dialog.showModal();if(flagPassageSelected&&inspectionMode==='flag')dialog.querySelector('.inspection-reason')?.scrollIntoView({block:'center'})}

function refreshLearningGuide(preferred){const page=location.hash==='#document-editor'?'documents':location.hash.slice(1)||'home';if(guideLastPage!==page){guidePreferred=null;guideLastPage=page}if(preferred)guidePreferred=preferred;if(inspectionOpen)guidePreferred='injection';const reportOpen=document.getElementById('report-dialog')?.open;if(reportOpen)guidePreferred='messagesReported';if(!learningGuide)learningGuide=createLearningGuide(id=>{guidePreferred=id;refreshLearningGuide()});learningGuide.update({page,state:{...state,sharedWorkshop:roomConnectionReady},preferred:guidePreferred,finale:state.approved&&!state.supportReported&&state.open?{url:supportLink(),canReport:state.activeRole==='VEN-01'}:null,portal:document.querySelector('dialog[open]')})}
function trackGuideContext(e){if(e.target.closest?.('#learning-guide'))return;const el=e.target.closest?.('[data-action],[data-guide-task],input,textarea,select');let task=el?.closest?.('[data-guide-task]')?.dataset.guideTask;const action=el?.dataset?.action;if(actionTasks[action])task=actionTasks[action];if(action?.startsWith('confirm-')&&tasks.some(t=>t.id===action.slice(8)))task=action.slice(8);const fields={prompt:'planned',contact:'verified','guest-brief':'guestBrief','report-reason':'messagesReported','report-notes':'messagesReported','scope-work':'safetyReady','scope-web':'safetyReady','contract-deposit':'financeReady','handoff-guests':'guestConfirmed','handoff-account':'venueConfirmed'};if(fields[el?.id])task=fields[el.id];if(action==='assistant-workspace')task='injection';if(action==='chat-current')task='planned';requestAnimationFrame(()=>refreshLearningGuide(task))}
document.addEventListener('click',trackGuideContext);
document.addEventListener('focusin',trackGuideContext);

function venueContract(){const signed=validContractSignature(state.contractCoSign);if(!contractOpen&&!signed)return `<section class="contract-access"><h3>Open the saved venue agreement</h3><p>Find the physical agreement and enter its printed digital-copy access code.</p><label for="contract-reference">Code on the physical venue agreement</label><input id="contract-reference" autocomplete="off"><button data-action="open-contract">Open digital agreement</button></section>`;const e=state.contractCoSign||{};return `<article class="venue-contract"><header><strong>GARDEN HOUSE EVENTS</strong><p>Venue agreement · Maya & Alex</p></header><h3>Venue package and payment terms</h3><dl><div><dt>Approved venue package</dt><dd>$7,000</dd></div><div><dt>Deposit</dt><dd>$2,000, included in the venue package</dd></div><div><dt>Verified account ending</dt><dd>4821</dd></div></dl><p>Keep step-free access and the agreed guest accommodations. Changes to the payee require independent verification.</p><section class="venue-signature"><strong>Venue representative</strong><p>Morgan · Garden House Events · Signed</p></section><h3>Finance co-signature</h3>${signed?`<p class="status">Co-signed by ${esc(e.name)} · ${esc(e.signedAt)}. Verified details saved.</p>${e.method==='drawn'?`<svg viewBox="0 0 600 180" class="signature-receipt" aria-label="Saved Finance co-signature">${signaturePaths(e.strokes).map(d=>`<path d="${d}"/>`).join('')}</svg>`:`<p class="typed-signature">${esc(e.typedName)}</p>`}`:`<input id="contract-reference-saved" type="hidden" value="VENUE-4821"><p>Compare this digital copy with the physical agreement before signing.</p><label for="contract-deposit">Deposit listed on the physical agreement ($)</label><input id="contract-deposit" type="number" inputmode="decimal"><label for="contract-account">Verified account ending</label><input id="contract-account" inputmode="numeric" maxlength="4"><label for="contract-signer">Your reviewer name</label><input id="contract-signer" maxlength="80" autocomplete="off"><label for="signature-method">Signing method</label><select id="signature-method"><option value="drawn">Draw with pen, mouse or touch</option><option value="typed">Accessible typed signature</option></select><p>Draw in the white area, or complete the typed alternative below.</p><svg id="contract-signature" viewBox="0 0 600 180" role="img" aria-label="Draw your co-signature here; a typed alternative follows"><g>${signaturePaths(contractStrokes).map(d=>`<path d="${d}"/>`).join('')}</g></svg><button data-action="clear-signature">Clear drawing</button><details><summary>Accessible typed signature</summary><label for="contract-typed-name">Type your reviewer name again</label><input id="contract-typed-name" maxlength="80"><label><input id="typed-signature-consent" type="checkbox">I intend this typed name to be my workshop co-signature.</label></details><button class="primary" data-action="sign-contract">Verify and co-sign agreement</button>`}</article>`}
app.addEventListener('pointerdown',e=>{const svg=e.target.closest?.('#contract-signature');if(!svg||contractStrokes.length>=60)return;const p=signaturePoint(e,svg);contractDrawing=[p];contractStrokes.push(contractDrawing);svg.setPointerCapture(e.pointerId);drawContractSignature(svg);e.preventDefault()});
app.addEventListener('pointermove',e=>{const svg=e.target.closest?.('#contract-signature');if(!svg||!contractDrawing||contractStrokes.flat().length>=1200)return;contractDrawing.push(signaturePoint(e,svg));drawContractSignature(svg)});
app.addEventListener('pointerup',()=>{contractDrawing=null});app.addEventListener('pointercancel',()=>{contractDrawing=null});
function signaturePoint(e,svg){const r=svg.getBoundingClientRect();return {x:Math.round(Math.max(0,Math.min(600,(e.clientX-r.left)/r.width*600))),y:Math.round(Math.max(0,Math.min(180,(e.clientY-r.top)/r.height*180)))}}
function drawContractSignature(svg){const group=svg.querySelector('g');group.replaceChildren(...signaturePaths(contractStrokes).map(d=>{const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);return path}))}

// Only known, currently available workshop records can be dragged into AI input.
app.addEventListener('dragstart',e=>{const file=e.target.closest('[data-workspace-file]');if(!file)return;e.dataTransfer.setData('application/x-blissify-file',file.dataset.workspaceFile);e.dataTransfer.effectAllowed='copy'});
app.addEventListener('dragover',e=>{const zone=e.target.closest('[data-workspace-drop]');if(zone&&Array.from(e.dataTransfer.types).includes('application/x-blissify-file')){e.preventDefault();e.dataTransfer.dropEffect='copy';zone.classList.add('drag-over')}});
app.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-workspace-drop]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drag-over')});
app.addEventListener('drop',e=>{const zone=e.target.closest('[data-workspace-drop]');if(!zone)return;e.preventDefault();zone.classList.remove('drag-over');const id=e.dataTransfer.getData('application/x-blissify-file');if(state.activeRole!=='PLN-03'||!availableFiles().includes(id))return;state.chatAttachments??=[];if(!state.chatAttachments.includes(id))state.chatAttachments.push(id);save();render()});

const supportRequestKey='blissify-support-request:'+reportChannel;
const supportAckKey='blissify-support-ack:'+reportChannel;
let reportPending=false;
async function receiveChatbotReport(raw){
 let request;try{request=JSON.parse(raw)}catch{return}
 if(!request?.id||reportPending)return;
 const valid=validSupportReport(request.report)&&Object.hasOwn(chatbotTopics,request.report?.topic||'');
 let message=!state.open?'Sign in to the Blissify workspace first.':taskReason('supportReported',state);
 if(!message&&!valid)message='Review the chatbot’s request and try again.';
 if(!message&&!state.supportReported){
  const patch={supportReport:request.report,supportReported:true,competitorDecision:'reported'};
  reportPending=true;
  try{
   if(roomConnection){
    const result=await roomConnection.update(patch);
    if(!result?.data.supportReported)message='Your report was not saved. Check your room connection and try again.';
   }else{
    Object.assign(state,patch);
    save();
   }
  }finally{reportPending=false}
 }
 const ok=!message;
 if(ok){
  message='Chatbot reported. No document was shared. The wedding is saved!';
  if(location.hash==='#debrief')render();else location.hash='debrief';
 }
 try{localStorage.setItem(supportAckKey,JSON.stringify({id:request.id,ok,message}));localStorage.removeItem(supportRequestKey)}catch{}
}
window.addEventListener('storage',e=>{if(e.key===supportRequestKey&&e.newValue)void receiveChatbotReport(e.newValue)});

installActionStyles();
